// #adfbdf (commit a9a4eb2): «דוח לרואה חשבון» /reports/accounting?from=2026-09-01&to=2026-11-18, печать (emulateMedia print, ширина 794):
//   в table.pd-table sub-строки ячейки (ח.פ. под именем клиента, сумма под «שולם חלקית», «מכירה מיידית» в «מסמך») имеют правый край
//   = правому краю первой строки ячейки (±1px) во всех строках; на экране то же.
// Метод: правый край считается по ГЛИФАМ (Range по текстовым узлам), а не по боксам — растянутый LTR-блок иначе скрыл бы баг.
//   Sub-строка = следующий узел ячейки, лежащий ниже первой строки (inline-соседи пропускаются). window.print не вызывается.
// Только чтение — @prod-safe.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const REPORT = '/reports/accounting?from=2026-09-01&to=2026-11-18';
const TOL = 1; // px

type Rec = { row: string; col: string; first: string; text: string; dx: number; below: boolean };

async function openReport(page: Page, media: 'print' | 'screen') {
  await page.emulateMedia({ media });
  await page.setViewportSize({ width: media === 'print' ? 794 : 1440, height: 1123 });
  await page.goto(REPORT);
  await expect(page.locator('table.pd-table tbody tr').first()).toBeVisible({ timeout: 30_000 });
  await expect(page.locator('table.pd-table tbody tr').first().locator('td').first()).not.toBeEmpty();
}

/** Для каждой ячейки с 2+ строками: смещение правого края глифов sub-строки от первой строки. */
function measure(page: Page): Promise<Rec[]> {
  return page.evaluate(() => {
    const BIDI = /[‎‏‪-‮⁦-⁩]/g;
    const norm = (s: string) => s.replace(BIDI, '').replace(/\s+/g, ' ').trim();
    const tbl = document.querySelector('table.pd-table')!;
    const heads = [...tbl.querySelectorAll('thead th')].map((th) => norm(th.textContent || ''));
    const glyph = (n: Node) => {
      const w = document.createTreeWalker(n, NodeFilter.SHOW_TEXT);
      const rects: DOMRect[] = [];
      for (let t = w.nextNode(); t; t = w.nextNode()) {
        if (!norm(t.textContent || '')) continue;
        const r = document.createRange();
        r.selectNodeContents(t);
        rects.push(...[...r.getClientRects()].filter((x) => x.width > 0 && x.height > 0));
      }
      if (!rects.length) return null;
      return { right: Math.max(...rects.map((x) => x.right)), top: Math.min(...rects.map((x) => x.top)), bottom: Math.max(...rects.map((x) => x.bottom)) };
    };
    const lines = (td: Element): Node[] => {
      let el: Element = td;
      const kids = (e: Element) => [...e.childNodes].filter((c) => (c.nodeType === 3 ? !!norm(c.textContent || '') : c.nodeType === 1 && !!norm((c as Element).textContent || '')));
      for (let k = kids(el); k.length === 1 && k[0].nodeType === 1; k = kids(el)) el = k[0] as Element;
      return kids(el);
    };
    const out: { row: string; col: string; first: string; text: string; dx: number; below: boolean }[] = [];
    for (const tr of tbl.querySelectorAll('tbody tr')) {
      const rowName = norm((tr.querySelector('td')?.textContent || '')) + ' | ' + norm(tr.textContent || '').slice(0, 60);
      [...tr.querySelectorAll('td')].forEach((td, i) => {
        const ls = lines(td);
        if (ls.length < 2) return;
        const f = glyph(ls[0]);
        if (!f) return;
        for (const l of ls.slice(1)) {
          const g = glyph(l);
          if (!g) continue;
          out.push({
            row: rowName, col: heads[i] ?? String(i), first: norm(ls[0].textContent || ''), text: norm(l.textContent || ''),
            dx: Math.round((g.right - f.right) * 10) / 10, below: g.top >= f.bottom - 1,
          });
        }
      });
    }
    return out;
  });
}

/** Только настоящие sub-строки (ниже первой строки ячейки). */
const subs = (all: Rec[]) => all.filter((r) => r.below);
const off = (rs: Rec[]) => rs.filter((r) => Math.abs(r.dx) > TOL).map((r) => `${r.col}: «${r.text}» под «${r.first}» dx=${r.dx}px (${r.row})`);

test.describe('דוח לרואה חשבון — יישור שורות-משנה בהדפסה (#adfbdf)', () => {
  test('הדפסה: כל שורות-המשנה בכל שורות הטבלה — הקצה הימני = הקצה הימני של השורה הראשונה בתא (±1px) #adfbdf @desktop @prod-safe', async ({ page }) => {
    await openReport(page, 'print');
    const rs = subs(await measure(page));
    expect(rs.length, 'в печатной таблице есть ячейки с sub-строками').toBeGreaterThan(0);
    expect(off(rs), 'ни одна sub-строка не смещена от правого края первой строки (>1px)').toEqual([]);
  });

  test('הדפסה: «לקוח» — ח.פ. מתחת לשם הלקוח; «תשלום» — הסכום מתחת ל«שולם חלקית» #adfbdf @desktop @prod-safe', async ({ page }) => {
    await openReport(page, 'print');
    const rs = subs(await measure(page));
    const taxIds = rs.filter((r) => r.col === 'לקוח' && /^\d{8,9}$/.test(r.text));
    expect(taxIds.length, 'есть строки ח.פ. под именем клиента').toBeGreaterThan(0);
    expect(off(taxIds), 'ח.פ. под именем, выровнен вправо (было ≈146px влево)').toEqual([]);
    const amounts = rs.filter((r) => r.col === 'תשלום' && r.text.includes('₪') && r.first.includes('שולם חלקית'));
    expect(amounts.length, 'есть суммы под «שולם חלקית»').toBeGreaterThan(0);
    expect(off(amounts), 'сумма под «שולם חלקית», выровнена вправо (было ≈80px влево)').toEqual([]);
  });

  test('הדפסה: «מסמך» — «מכירה מיידית» מתחת למספר המסמך, מיושר לימין #adfbdf @desktop @prod-safe', async ({ page }) => {
    await openReport(page, 'print');
    const walkIn = subs(await measure(page)).filter((r) => r.col === 'מסמך' && r.text.includes('מכירה מיידית'));
    test.skip(walkIn.length === 0, 'в диапазоне 01.09–18.11.2026 нет sub-строки «מכירה מיידית» в колонке «מסמך» (данные изменились)');
    expect(off(walkIn), '«מכירה מיידית» выровнена по правому краю первой строки ячейки').toEqual([]);
  });

  test('מסך (בלי הדפסה): אותו יישור — בלי שינוי #adfbdf @desktop @prod-safe', async ({ page }) => {
    await openReport(page, 'screen');
    const rs = subs(await measure(page));
    expect(rs.length, 'на экране есть ячейки с sub-строками').toBeGreaterThan(0);
    expect(off(rs), 'на экране sub-строки выровнены так же').toEqual([]);
  });
});
